        return True

    direction = None

    for i in range(len(l) - 1):
        diff = l[i+1] - l[i]
        if diff == 0:
            continue

        if direction is None:
            direction = 1 if diff > 0 else -1
        else:
            if (direction == 1 and diff < 0) or (direction == -1 and diff > 0):
                return False

