    if len(l) <= 2:
        return True

    direction = None
    for i in range(len(l) - 1):
        diff = l[i + 1] - l[i]
        if diff == 0:
            continue
        if direction is None:
            direction = diff > 0
        else:
            if (direction and diff < 0) or (not direction and diff > 0):
                return False
    return True

