def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    sorted_arr = sorted(arr)

    # Find the first index where the current array differs from the sorted array
    pivot = -1
    for i in range(n):
        if arr[i] != sorted_arr[i]:
            pivot = i
            break

    # If no differences found, array is already sorted
    if pivot == -1:
        return True

    # Compare the remaining part of the array with the beginning of the sorted array
    # to check if the array is a rotation of the sorted array
    for i in range(n):
        if arr[(pivot + i) % n] != sorted_arr[i]:
            return False

    return True
