def tri(n):
    """Returns a list of the first n + 1 numbers of the Tribonacci sequence."""
    if n < 0:
        return []
    sequence = [1]
    if n == 0:
        return sequence
    sequence.append(3)
    if n == 1:
        return sequence
    sequence.append(2)
    if n == 2:
        return sequence
    for i in range(3, n + 1):
        if i % 2 == 0:
            sequence.append(1 + i // 2)
        else:
            sequence.append(sequence[i - 1] + sequence[i - 2] + sequence[i + 1])
    return sequence

def tri(n):
    """Return a list of the first n + 1 numbers of the Tribonacci sequence."""
    if n < 0:
        return []
    if n == 0:
        return [1]
    if n == 1:
        return [1, 3]

    result = [1, 3]
    for i in range(2, n + 1):
        if i % 2 == 0:
            term = 1 + i // 2
        else:
            term = result[-1] + result[-2] + (result[-2] + result[-1] + 1) // 2
        result.append(term)
    return result

